"""Transform function for task-41f2bcc6.

Pattern: Points on border segments create perpendicular beams.
- Top border markers: beams go DOWN (4 at offset 3, then marker value)
- Bottom border markers: beams go UP (4 at offset 3, then marker value)
- Beam value = 8 in demo5 (the lowest non-background value)
"""

def transform(grid):
    """Apply the learned transformation pattern to a grid."""
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    # Find background (most common value)
    from collections import Counter
    all_vals = []
    for row in grid:
        all_vals.extend(row)
    bg = Counter(all_vals).most_common(1)[0][0]

    # Result starts as copy of input
    result = [row[:] for row in grid]

    # Handle top border markers (create downward beams)
    for c in range(W):
        if grid[0][c] != bg:
            marker_val = grid[0][c]
            for r in range(1, H):
                if r <= 3:
                    result[r][c] = 4
                else:
                    result[r][c] = marker_val

    # Handle bottom border markers (create upward beams)
    for c in range(W):
        if grid[H-1][c] != bg:
            marker_val = grid[H-1][c]
            for r in range(H-2, -1, -1):
                if r >= H-3:
                    result[r][c] = 4
                else:
                    result[r][c] = marker_val

    return result
